-- Customer accounts and the platform operator (ADR M15-0001, M3-0002). Generated by Drizzle Kit, then edited by hand:
-- the operator role is created first (a policy below names it), the placeholder plans are seeded before firm.plan_code
-- references them, and the firm account columns are added nullable, backfilled, then constrained (rule 8).
-- Roles, grants, functions and triggers are in the custom migration 0020.

-- canopy_operator: the operator console's database role (ADR M15-0001 decision 8, M3-0002). No login, no BYPASSRLS.
-- The operator login is a member and switches to it with SET LOCAL ROLE; the migrating user needs no membership.
DO $$
BEGIN
  CREATE ROLE canopy_operator NOLOGIN NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE;
EXCEPTION WHEN OTHERS THEN
  IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = 'canopy_operator') THEN
    RAISE;
  END IF;
END
$$;
