-- Every firm so far is a consultancy on the unlimited plan, active (ADR M15-0001 decision 1).
-- FORCE RLS binds the owner, so each firm is updated as itself (its ids come from canopy_list_firm_ids, which runs
-- as canopy_lookup). A firm left null would fail the SET NOT NULL below rather than be skipped silently.
DO $$
DECLARE f uuid;
BEGIN
  FOR f IN SELECT canopy_list_firm_ids() LOOP
    PERFORM set_config('app.firm_id', f::text, true), set_config('app.firm_staff', 'on', true);
    UPDATE "firm" SET "kind" = 'CONSULTANCY', "status" = 'ACTIVE', "plan_code" = 'CONSULTANCY' WHERE "id" = f;
  END LOOP;
  PERFORM set_config('app.firm_id', '', true), set_config('app.firm_staff', '', true);
END
$$;
--> statement-breakpoint
